css:
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #f3f4f6;
  color: #18181b;
  font-family: system-ui, sans-serif;
}

.card {
  max-width: 420px;
  padding: 32px;
  border-radius: 20px;
  background: white;
  box-shadow: 0 16px 48px #00000014;
}

.eyebrow {
  color: #52525b;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .12em;
}

button {
  padding: 12px 16px;
  border: 0;
  border-radius: 10px;
  background: #18181b;
  color: white;
  font: inherit;
  cursor: pointer;
}

